#include "platform/app_icon.h"

#include <SDL3/SDL.h>

#include <cstddef>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>

// gd01_icon_data.cpp / gd01_icon_small_data.cpp, generated by CMake.
extern const unsigned char kGd01IconPng[], kGd01IconSmallPng[];
extern const std::size_t kGd01IconPngSize, kGd01IconSmallPngSize;

namespace {

SDL_Surface* loadIcon(const unsigned char* data = kGd01IconPng, std::size_t size = kGd01IconPngSize) {
    SDL_IOStream* io = SDL_IOFromConstMem(data, size);
    if (!io) return nullptr;
    SDL_Surface* png = SDL_LoadPNG_IO(io, true);
    if (!png) return nullptr;
    SDL_Surface* rgba = SDL_ConvertSurface(png, SDL_PIXELFORMAT_RGBA32);
    SDL_DestroySurface(png);
    return rgba;
}

}  // namespace

void setAppWindowIcon(SDL_Window* window) {
#ifndef __ANDROID__
    if (!window) return;
    if (SDL_Surface* icon = loadIcon()) {
        // The badge's centre for the small sizes (title bar, taskbar): its letters stay readable.
        if (SDL_Surface* small = loadIcon(kGd01IconSmallPng, kGd01IconSmallPngSize)) {
            SDL_AddSurfaceAlternateImage(icon, small);
            SDL_DestroySurface(small);
        }
        SDL_SetWindowIcon(window, icon);
        SDL_DestroySurface(icon);
    }
#else
    (void)window;
#endif
}

bool appIconImage(Image& out) {
    SDL_Surface* icon = loadIcon();
    if (!icon) return false;
    out.width = icon->w, out.height = icon->h;
    out.rgba.resize(size_t(icon->w) * size_t(icon->h) * 4);
    for (int y = 0; y < icon->h; ++y)
        std::memcpy(out.rgba.data() + size_t(y) * size_t(icon->w) * 4,
                    static_cast<const unsigned char*>(icon->pixels) + size_t(y) * size_t(icon->pitch), size_t(icon->w) * 4);
    SDL_DestroySurface(icon);
    return true;
}

void installDesktopEntry() {
#if defined(__linux__) && !defined(__ANDROID__)
    namespace fs = std::filesystem;
    if (SDL_getenv("GD01_NO_DESKTOP_ENTRY")) return;
    std::error_code ec;
    const fs::path exe = fs::read_symlink("/proc/self/exe", ec);
    if (ec || !fs::exists(exe.parent_path() / "LICENSE", ec)) return;  // a development build
    const char* xdg = SDL_getenv("XDG_DATA_HOME");
    const char* home = SDL_getenv("HOME");
    if ((!xdg || !*xdg) && (!home || !*home)) return;
    const fs::path data = xdg && *xdg ? fs::path(xdg) : fs::path(home) / ".local" / "share";
    const fs::path icon = data / "icons" / "hicolor" / "256x256" / "apps" / "io.github.mbracali.gd01.png";
    const fs::path entry = data / "applications" / "io.github.mbracali.gd01.desktop";
    std::ostringstream want;
    want << "[Desktop Entry]\nType=Application\nName=GD Engine 01\n"
         << "GenericName=Guitar Hero (PS2) on Guitar Dream Engine\nComment=Play Guitar Hero (PS2) from your own disc image\n"
         << "Exec=\"" << exe.string() << "\"\nPath=" << exe.parent_path().string() << "\nIcon=io.github.mbracali.gd01\n"
         << "Terminal=false\nCategories=Game;\nStartupWMClass=io.github.mbracali.gd01\n";
    std::ifstream have(entry);
    std::stringstream old;
    old << have.rdbuf();
    if (old.str() == want.str() && fs::exists(icon, ec)) return;  // already pointing here
    fs::create_directories(icon.parent_path(), ec);
    fs::create_directories(entry.parent_path(), ec);
    std::ofstream(icon, std::ios::binary).write(reinterpret_cast<const char*>(kGd01IconPng), std::streamsize(kGd01IconPngSize));
    std::ofstream(entry) << want.str();
    SDL_Log("Application menu entry written: %s", entry.string().c_str());
#endif
}
